1| class IntervalMap:
2|     """
3|     This class creates a lookup table for contiguous ranges that can be
4|     described by a single length. It stores a mapping of these ranges to an
5|     arbitrary object allowing one to encode mappings like:
6| 
7|     ..code-block::
8| 
9|         range(0, 100000)        -> SomeObject()
10|         range(100000, 100012)   -> AnotherObject()
11|         range(100012, 200000)   -> AThirdObject()
12| 
13|     in a space efficient manner. The example map above would be constructed as
14|     follows with an interval map:
15| 
16|     ..code-block::
17| 
18|         im = IntervalMap()
19|         im.append_interval(100000, SomeObject())
20|         im.append_interval(12, AnotherObject())
21|         im.append_interval(99988, AThirdObject())
22| 
23|     The total length of the entire range can be queried using the `len()`
24|     operator, but one should prefer the `len` property since the len-operator
25|     will fail for very large arrays (> sys.maxint):
26| 
27|     ..code-block::
28| 
29|         len(im)
30|         -> 200000
31| 
32|     Lookups can be done with the usual `[]` operator:
33| 
34|     ..code-block::
35| 
36|         im[5000]
37|         -> SomeObject
38|         im[12300]
39|         -> AThridObject
40|         im[1242342134]
41|         -> raises IndexError
42| 
43|     Note that negative indexes are not allowed.
44|     """
45| 
46|     def __init__(self):
47|         self.__endpoints = []
48| 
49|     def append_interval(self, length, label):
50|         self.__endpoints.append((self.len + length, label))
51|         self.__endpoints.sort()
52| 
53|     def __find_endpoint_index(self, i):
54|         def find(start, end):
55|             # use nested intervals to find correct label
56|             if start == end:
57|                 return start
58| 
59|             else:
60|                 mid = (start + end) // 2
61|                 if self.__endpoints[mid][0] > i:
62|                     return find(start, mid)
63| 
64|                 else:
65|                     return find(mid + 1, end)
66| 
67|         if i < 0 or i >= self.len:
68|             return None
69| 
70|         else:
71|             return find(0, len(self.__endpoints))
72| 
73|     def get_offset(self, i):
74|         """
75|         Tries to find the start point of an interval that was added through
76|         append_interval that is indexed by i.
77| 
78|         Arguments
79|         ---------
80|         i: int
81|             The index of an item for which to find the start-point of its
82|             interval.
83| 
84|         Returns
85|         -------
86|         Integer value describing the start point of the interval that i falls
87|         into.
88| 
89|         Raises
90|         ------
91|         IndexError:
92|             In case that i does not fall in any interval/
93|         """
94|         if not isinstance(i, int):
95|             raise TypeError("index must be int")
96| 
97|         endpoint_index = self.__find_endpoint_index(i)
98|         if endpoint_index is None:
99|             raise IndexError()
100| 
101|         elif endpoint_index == 0:
102|             return 0
103| 
104|         else:
105|             return self.__endpoints[endpoint_index - 1][0]
106| 
107|     def __getitem__(self, i):
108|         if not isinstance(i, int):
109|             raise TypeError("index must be int")
110| 
111|         if i < 0:
112|             raise IndexError()
113| 
114|         endpoint_index = self.__find_endpoint_index(i)
115|         if endpoint_index is None:
116|             raise IndexError()
117| 
118|         else:
119|             return self.__endpoints[endpoint_index][1]
